def topo_sort(num_nodes: int, edges: list[tuple[int, int]]) -> list[int]:
    adj = [[] for _ in range(num_nodes)]
    in_degree = [0] * num_nodes
    for u, v in edges:
        adj[u].append(v)
        in_degree[v] += 1

    queue = [i for i in range(num_nodes) if in_degree[i] == 0]
    result = []

    while queue:
        u = queue.pop(0)
        result.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if len(result) != num_nodes:
        raise ValueError("cycle")

def all_segmentations(s: str, words: set[str]) -> list[str]:
    memo = {}

    def helper(i: int) -> list[str]:
        if i == len(s):
            return [""]
        if i in memo:
            return memo[i]

        results = []
        for j in range(i + 1, len(s) + 1):
            word = s[i:j]
            if word in words:
                suffixes = helper(j)
                for suffix in suffixes:
                    if suffix:
                        results.append(word + " " + suffix)
                    else:
                        results.append(word)
